sys_ws_operation.operation_script:
(function process(request, response) {
  try {
    var body = request.body ? request.body.data : {};
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (e) { body = {}; }
    }
    if (!body) body = {};
    var engine = new x_snc_testreach.TestReachRiskEngine();
    var result = engine.dispatch(body);
    if (!result.ok) {
      response.setStatus(result.http_status || 400);
    } else {
      response.setStatus(result.http_status || 200);
    }
    response.setContentType('application/json');
    var payload = result.ok ? { ok: true, data: result.data } : { ok: false, error: result.error };
    response.getStreamWriter().writeString(JSON.stringify(payload));
  } catch (e) {
    response.setStatus(500);
    response.setContentType('application/json');
    response.getStreamWriter().writeString(JSON.stringify({
      ok: false,
      error: 'Unhandled exception: ' + (e.message || e.toString())
    }));
  }
})(request, response);
